package com.bmiller.uzzu.schedule

import com.bmiller.uzzu.playlist.League
import com.bmiller.uzzu.playlist.normalizeName
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json

/** One row of the bundled assets/teams.json (generated by tools/generate_teams.py). */
@Serializable
data class TeamEntry(
    val league: League,
    val displayName: String,
    val location: String = "",
    val name: String = "",
    val shortDisplayName: String = "",
    val abbreviation: String = "",
    val aliases: List<String> = emptyList(),
) {
    /**
     * Normalized full names that identify this team: display name, "location nickname" and aliases.
     * Nickname, short name and abbreviation are deliberately excluded (Giants, Rangers, Kings... collide).
     */
    val fullNames: Set<String>
        get() = buildSet {
            add(normalizeName(displayName))
            if (location.isNotBlank() && name.isNotBlank()) add(normalizeName("$location $name"))
            aliases.forEach { add(normalizeName(it)) }
        }
}

@Serializable
private data class TeamsFile(val teams: List<TeamEntry>)

/** Offline NFL/MLB/NHL/NBA team lookup by normalized full name. */
class TeamDictionary(val teams: List<TeamEntry>) {
    private val byName: Map<String, List<TeamEntry>> = buildMap<String, MutableList<TeamEntry>> {
        for (t in teams) for (n in t.fullNames) getOrPut(n) { mutableListOf() } += t
    }

    /** Teams whose full name or alias equals [name] after normalization. */
    fun lookup(name: String): List<TeamEntry> = byName[normalizeName(name)].orEmpty()

    /** The dictionary entry for an ESPN competitor of [league], matched by its display name. */
    fun entryFor(league: League, espnDisplayName: String): TeamEntry? =
        lookup(espnDisplayName).firstOrNull { it.league == league }

    companion object {
        private val json = Json { ignoreUnknownKeys = true }
        fun parse(text: String) = TeamDictionary(json.decodeFromString<TeamsFile>(text).teams)
    }
}

/** PLAN Step 2: a game's league is set only when away and home both resolve to the same league. */
class LeagueClassifier(private val dictionary: TeamDictionary) {
    fun classify(away: String, home: String): League {
        if (away.isBlank() || home.isBlank()) return League.UNGROUPED
        val common = dictionary.lookup(away).map { it.league }.toSet() intersect
            dictionary.lookup(home).map { it.league }.toSet()
        return common.singleOrNull() ?: League.UNGROUPED
    }
}
